const SCALING_TIERS = [
  { minEquity:0,      maxEquity:14999,  maxMicros:2,  maxStandard:0,  label_en:'Starter',    label_pt:'Iniciante',   label_es:'Principiante' },
  { minEquity:15000,  maxEquity:24999,  maxMicros:5,  maxStandard:1,  label_en:'Growing',    label_pt:'Crescendo',   label_es:'Creciendo'    },
  { minEquity:25000,  maxEquity:39999,  maxMicros:10, maxStandard:2,  label_en:'Building',   label_pt:'Construindo', label_es:'Construyendo'  },
  { minEquity:40000,  maxEquity:59999,  maxMicros:15, maxStandard:3,  label_en:'Advancing',  label_pt:'Avançando',   label_es:'Avanzando'    },
  { minEquity:60000,  maxEquity:999999, maxMicros:20, maxStandard:5,  label_en:'Professional',label_pt:'Profissional',label_es:'Profesional'  },
];

function getScalingTier(equity) {
  return SCALING_TIERS.find(t => equity >= t.minEquity && equity <= t.maxEquity) || SCALING_TIERS[0];
}

