    id:'oil_inventory', impact:'orange',
    name_en:'EIA Crude Oil Inventory Report', name_pt:'Relatório de Estoques de Petróleo EIA', name_es:'Informe de Inventarios de Petróleo EIA',
    schedule:'Every Wednesday · 10:30 AM EST',
