// ── HELPER FUNCTIONS ──
function generateCandles(basePrice, count=50, bullish=true, seed=1) {
  const candles=[];
  let price=basePrice*(bullish?0.91:1.09);
  // Use seed to make generation deterministic per instrument
  let rng = seed;
  function rand() { rng = (rng * 9301 + 49297) % 233280; return rng / 233280; }
  for(let i=0;i<count;i++){
    const trend=bullish?0.004:-0.003;
    const open=price;
    const change=(rand()-0.47+trend)*0.018;
    const close=open*(1+change);
    const high=Math.max(open,close)*(1+rand()*0.009);
    const low=Math.min(open,close)*(1-rand()*0.009);
    candles.push({open,high,low,close,bull:close>=open,volume:Math.floor(rand()*5000000+500000)});
    price=close;
  }
  return candles;
}

function toHeikinAshi(candles) {
  const ha=[];
  for(let i=0;i<candles.length;i++){
    const c=candles[i];
    const haClose=(c.open+c.high+c.low+c.close)/4;
    const haOpen=i===0?(c.open+c.close)/2:(ha[i-1].open+ha[i-1].close)/2;
    const haHigh=Math.max(c.high,haOpen,haClose);
    const haLow=Math.min(c.low,haOpen,haClose);
    ha.push({open:haOpen,high:haHigh,low:haLow,close:haClose,bull:haClose>=haOpen,volume:c.volume});
  }
  return ha;
}

function generateCalendarData() {
  const data={};
  const now=new Date();
  for(let d=1;d<=now.getDate();d++) data[d]=Math.floor((Math.random()-0.38)*300);
  return data;
}

function convertTimeToUserTZ(estHour, estMinute, userTzOffset) {
  const estOffset=-5;
  const diff=userTzOffset-estOffset;
  let hour=estHour+diff;
  let day='';
  if(hour<0){hour+=24;day=' (prev day)';}
  if(hour>=24){hour-=24;day=' (next day)';}
  const h=hour%12||12;
  const ampm=hour<12?'AM':'PM';
  const min=estMinute===0?'00':estMinute;
  return `${h}:${min} ${ampm}${day}`;
}

function getPropFirmsForCountry(countryCode) {
  return PROP_FIRMS.filter(f=>f.eligible_codes.includes(countryCode));
}

function getBrokeragesForCountry(countryCode) {
  return BROKERAGES.filter(b=>b.available_codes.includes(countryCode));
}

function getQuizBonus(score, total) {
  const pct=score/total;
  if(pct>=0.9) return 100;
  if(pct>=0.8) return 75;
  if(pct>=0.7) return 50;
  return 0;
}

// Swing point detection for auto-placed Fibonacci
function detectSwingPoints(candles) {
  const len = candles.length;
  let swingHighIdx = 0;
  let swingLowIdx = 0;
  let maxHigh = candles[0].high;
  let minLow = candles[0].low;
  // Look at last 30 candles for swing detection
  const lookback = Math.min(30, len);
  const start = len - lookback;
  for(let i = start; i < len; i++) {
    if(candles[i].high > maxHigh) { maxHigh = candles[i].high; swingHighIdx = i; }
    if(candles[i].low < minLow)   { minLow  = candles[i].low;  swingLowIdx  = i; }
  }
  return { swingHighIdx, swingLowIdx, swingHigh: maxHigh, swingLow: minLow };
}

// Detect recent supply zone (last major bearish candle cluster)
function detectSupplyZone(candles) {
  const len = candles.length;
  for(let i = len - 5; i >= Math.max(0, len - 25); i--) {
    const c = candles[i];
    if(!c.bull && (c.high - c.low) > (c.high * 0.008)) {
      return { top: c.high * 1.002, bottom: c.open * 0.998 };
    }
  }
  return null;
}

// Detect recent demand zone (last major bullish candle cluster)
function detectDemandZone(candles) {
  const len = candles.length;
  for(let i = len - 5; i >= Math.max(0, len - 25); i--) {
    const c = candles[i];
    if(c.bull && (c.high - c.low) > (c.high * 0.008)) {
      return { top: c.close * 1.002, bottom: c.low * 0.998 };
    }
  }
  return null;
}// ════════════════════════════════════════
