// ── CHART TOOLTIP ──
function ChartTooltip({ lang, onDone }) {
  const [step, setStep] = useState(0);
  const tips = [
    { icon:'👆', en:'Tap any instrument to load it on the chart. Long-term stocks are in the Portfolio tab.',                                     pt:'Toque em qualquer instrumento para carregá-lo no gráfico. Ações de longo prazo estão na aba Portfólio.',                                    es:'Toca cualquier instrumento para cargarlo en el gráfico. Las acciones a largo plazo están en la pestaña Portafolio.'                                   },
    { icon:'🔷', en:'Switch chart types using the icons next to timeframes. Heikin Ashi smooths noise to show trend strength clearly.',           pt:'Alterne tipos de gráfico usando os ícones. Heikin Ashi suaviza o ruído para mostrar a força da tendência claramente.',                       es:'Cambia tipos de gráfico usando los íconos. Heikin Ashi suaviza el ruido para mostrar la fuerza de la tendencia claramente.'                          },
    { icon:'📐', en:'Use the drawing toolbar to auto-place Fibonacci, trend lines, supply/demand zones, and key horizontal levels on the chart.',  pt:'Use a barra de ferramentas de desenho para colocar automaticamente Fibonacci, linhas de tendência e zonas de oferta/demanda no gráfico.',    es:'Usa la barra de herramientas de dibujo para colocar automáticamente Fibonacci, líneas de tendencia y zonas de oferta/demanda en el gráfico.'         },
    { icon:'🧠', en:'Every trade starts with an emotion check and 3-question pre-trade checklist. Trading psychology in practice — not just theory.', pt:'Todo trade começa com uma verificação emocional e checklist pré-trade de 3 perguntas. Psicologia do trading na prática — não apenas teoria.', es:'Cada operación comienza con una verificación emocional y checklist pre-operación de 3 preguntas. Psicología del trading en práctica — no solo teoría.' },
    { icon:'⤢', en:'Tap ⤢ for true landscape fullscreen mode. Use − and + for quantity. The chart quantity field never causes chart redraws.',      pt:'Toque ⤢ para modo paisagem em tela cheia. Use − e + para quantidade. O campo de quantidade nunca causa redesenhos do gráfico.',             es:'Toca ⤢ para modo paisaje en pantalla completa. Usa − y + para cantidad. El campo de cantidad nunca causa redibujos del gráfico.'                      },
  ];
  const tip = tips[step];
  return(
    <View style={s.tooltipOverlay}>
      <View style={s.tooltipCard}>
        <Text style={s.tooltipIcon}>{tip.icon}</Text>
        <Text style={s.tooltipStep}>{lang==='pt'?`Dica ${step+1} de ${tips.length}`:lang==='es'?`Consejo ${step+1} de ${tips.length}`:`Tip ${step+1} of ${tips.length}`}</Text>
        <Text style={s.tooltipText}>{tip[lang]||tip.en}</Text>
        <TouchableOpacity style={[s.tooltipBtn,{marginTop:14}]} onPress={()=>step<tips.length-1?setStep(s=>s+1):onDone()}>
          <Text style={s.tooltipBtnText}>{step<tips.length-1?(lang==='pt'?'Próxima →':lang==='es'?'Siguiente →':'Next →'):(lang==='pt'?'Entendido!':lang==='es'?'¡Entendido!':"Let's go!")}</Text>
        </TouchableOpacity>
      </View>
    </View>
  );
}

